<section class="page-heading"><div><p class="eyebrow">VOS PIÈCES ET COMBINAISONS PRÉFÉRÉES</p><h1>Favoris</h1><p class="subheading">Retrouvez ici les pièces et tenues que vous avez enregistrées.</p></div></section>
<section class="section-head"><div><p class="eyebrow">GARDE-ROBE</p><h2>Vêtements favoris</h2></div></section><?php if(!$clothes): ?><p class="subheading">Aucun vêtement favori pour le moment.</p><?php else: ?><div class="clothes-grid"><?php foreach($clothes as $item): ?><a class="clothing-card" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>"><div class="clothing-photo"><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt=""><?php else: ?><span>GRINGO</span><?php endif; ?></div><div class="clothing-meta"><span><?= e($item['label_name']) ?></span><h3><?= e($item['name']) ?></h3><?php $rating=$item['rating'];require APP_ROOT.'/app/views/partials/rating-display.php'; ?></div></a><?php endforeach; ?></div><?php endif; ?>
<section class="section-head section-spaced"><div><p class="eyebrow">COMPOSITIONS</p><h2>Tenues favorites</h2></div></section><?php if(!$outfits): ?><p class="subheading">Aucune tenue favorite pour le moment.</p><?php else: ?><div class="clothes-grid"><?php foreach($outfits as $outfit): $pieces=$piecesByOutfit[(int)$outfit['id']]??[]; ?><a class="clothing-card" href="<?= e(url('outfits-show',['id'=>$outfit['id']])) ?>"><?php if($pieces): ?><div class="outfit-collage outfit-card-collage" aria-label="Toutes les pièces de <?= e($outfit['name']) ?>"><?php foreach($pieces as $piece): ?><div class="outfit-collage-piece"><?php if($piece['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$piece['image_path']) ?>" alt="<?= e($piece['name']) ?>"><?php else: ?><span><?= e(mb_strtoupper(mb_substr($piece['name'],0,1))) ?></span><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?><div class="clothing-meta"><span>♥ FAVORI</span><h3><?= e($outfit['name']) ?></h3><?php $rating=$outfit['rating'];require APP_ROOT.'/app/views/partials/rating-display.php'; ?></div></a><?php endforeach; ?></div><?php endif; ?>
